import{G as e,W as t,n,rt as r}from"./chunks/framework.BR9-gX-M.js";var i=JSON.parse(`{"title":"Using it with an AI agent - automatica11y","description":"","frontmatter":{},"headers":[],"relativePath":"agents.md","filePath":"agents.md"}`),a={name:`agents.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="using-it-with-an-ai-agent" tabindex="-1">Using it with an AI agent. <a class="header-anchor" href="#using-it-with-an-ai-agent" aria-label="Permalink to “Using it with an AI agent.”">​</a></h1><p>The tool prints its own guidance, so any agent that can run <code>npx</code> can learn to use it. If the tool is installed globally, the agent can run <code>automatica11y guide skill</code> instead of <code>npx automatica11y@latest guide skill</code>:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> automatica11y@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> guide</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">           # where to start (the AGENTS.md file)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> automatica11y@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> guide</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">     # the full steps: build the command, run it, write the report</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> automatica11y@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> guide</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fixtures</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # how to write the fixtures an npm package needs</span></span></code></pre></div><p>The guidance ships with the tool, so it always matches the version you run. Tell your agent to run <code>npx automatica11y@latest guide</code> and follow it, then ask for things like &quot;How accessible is Radix Dialog?&quot; or &quot;Compare the accessibility of React Aria and Headless UI.&quot; The agent needs to run shell commands and read and write files. Nothing here is tied to one agent.</p><h2 id="skills" tabindex="-1">Skills. <a class="header-anchor" href="#skills" aria-label="Permalink to “Skills.”">​</a></h2><p>If your agent loads skills from a folder, copy <a href="https://github.com/thedannywahl/automatica11y/tree/main/skills/automatica11y" target="_blank" rel="noreferrer"><code>skills/automatica11y</code></a> into it. That&#39;s one small file, <code>SKILL.md</code>. It advertises the tool to the agent, and sends it to <code>guide skill</code>. It names no version, so it doesn&#39;t go stale. The full steps are the <a href="https://github.com/thedannywahl/automatica11y/tree/main/skills/automatica11y-runner" target="_blank" rel="noreferrer"><code>automatica11y-runner</code></a> skill, which ships in the package and is what <code>guide skill</code> prints. Copy it too if you want the steps available without the network. They&#39;re also on this site as <a href="./agent-steps">the agent steps</a>.</p><h2 id="agents-md" tabindex="-1">AGENTS.md. <a class="header-anchor" href="#agents-md" aria-label="Permalink to “AGENTS.md.”">​</a></h2><p><a href="https://github.com/thedannywahl/automatica11y/blob/main/AGENTS.md" target="_blank" rel="noreferrer"><code>AGENTS.md</code></a> is for agents that read it but don&#39;t load skills. It points to the same steps, and tells contributors how to run and change the code.</p><h2 id="version-safety" tabindex="-1">Version safety. <a class="header-anchor" href="#version-safety" aria-label="Permalink to “Version safety.”">​</a></h2><p>The steps name the version series they were written for, and the first thing they do is check it. If the installed tool is the wrong series, the agent stops and says so, instead of running steps that don&#39;t match. An installed copy can be older than the steps expect. In that case use <code>npx</code>, which always fetches the latest.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};